import json
import re
import splunk.pdf.pdfgen_utils as pdfgen_utils

from splunk.rest import simpleRequest
from splunk.pdf.studio.spl_keywords import reserved_words

logger = pdfgen_utils.getLogger()
QUOTE = "'"
DOT = "."
SLASH = "/"
PARENT = ".."
SHORTCUT = "~"
INDEXES_SHORTCUT = "~indexes"

def dequote(value: str):
    return value[1:len(value)-1] if (value.startswith(QUOTE) and value.endswith(QUOTE)) else value

def segment(namespace: str):
    parts = []
    context = 0
    in_quote = False

    i = 0
    while i < len(namespace):
        c = namespace[i]

        if c == QUOTE:
            in_quote = not in_quote
        
        if not in_quote:
            if c == DOT or c == SLASH:
                if c == DOT and namespace[i+1] == DOT:
                    parts.append(PARENT)
                    i += 1
                else:
                    if context != i:
                        part = namespace[context:i]
                        if part:
                            parts.append(part)
                    parts.append(c)
                context = i + 1
            if i == len(namespace) - 1:
                if context != i:
                    part = namespace[context:i+1]
                    if part:
                        parts.append(part)
        i += 1
    return list(map(dequote, parts))

def escape_identifier(id: str):
    if id in reserved_words:
        return "'" + id + "'"
    
    pattern = re.compile(r"^[a-zA-Z_][a-zA-Z_0-9]*$")
    
    if not pattern.match(id):
        escaped = "'"

        i = 0
        while i < len(id):
            c = id[i]

            if c == "'":
                escaped += "\\'"
            elif c == "\\":
                    escaped += "\\\\"
            elif c == "$":
                if i < len(id) - 1 and id[i+1] == "{":
                    escaped += "\\${"
                    i += 1
                else:
                    escaped += "$"
            else:
                escaped += c
            i += 1
        return escaped + "'"
    return id

def escape_segment(segment: str):
    if segment in [SHORTCUT, INDEXES_SHORTCUT, SLASH, DOT, PARENT]:
        return segment
    return escape_identifier(segment)

def escape_namescape(namespace: str):
    segments = segment(namespace)
    if (
        (len(segments) >= 2) and
        (segments[0] == SHORTCUT) and
        (segments[1] == DOT)
    ):
        segments[1] = SLASH
    return ''.join(map(escape_segment, segments))

def generate_spl2_view_query(view: str, namespace = ""):
    trimmed_view = escape_identifier(view.strip())
    trimmed_namespace = escape_namescape(namespace.strip())
    if not trimmed_namespace:
        return f"| @spl2 | from {trimmed_view}"
    return f"| @spl2 | from {trimmed_namespace}.{trimmed_view}"

def get_spl2_module_metadata(namespace: str, session_key: str):
    spl2_modules_endpoint = "orchestrator/v1/spl2/modules"
    url = f"{spl2_modules_endpoint}/{namespace}"

    try:
        res, content = simpleRequest(url, method="GET", sessionKey=session_key, getargs={"output_mode": "json"})
        if res.status != 200:
            raise Exception
        byte_json = content.decode('utf-8')
        module_metadata = json.loads(byte_json)
        return module_metadata
    except Exception:
        logger.error('Failed to fetch SPL2 module metadata for namespace: %s', namespace)
        return {}